-- =====================================================================
-- 10_ref_mlit.sql：国土交通省「国土数値情報」から作った REF テーブル（tools/prepare_mlit.py で自動生成。手で編集しない）
-- 駅別乗降客数（S12、乗降客数は最新 2024 年度。0・欠損は直近年度の値）／鉄道（N02）／行政区域（N03）／500mメッシュ別将来推計人口
-- 出典：国土交通省 国土数値情報（https://nlftp.mlit.go.jp/ksj/）を加工して作成
-- =====================================================================

CREATE OR REPLACE TABLE DF_HANDSON.REF.WARD_RAW (WARD_CODE STRING, WARD_NAME STRING, GEOJSON STRING);







CREATE OR REPLACE TABLE DF_HANDSON.REF.WARD AS
SELECT WARD_CODE, WARD_NAME, GEOJSON, TO_GEOGRAPHY(GEOJSON, TRUE) AS GEO FROM DF_HANDSON.REF.WARD_RAW;

DROP TABLE DF_HANDSON.REF.WARD_RAW;

CREATE OR REPLACE TABLE DF_HANDSON.REF.STATION_RAW (STATION_ID STRING, STATION_NAME STRING, OPERATORS STRING, LINES STRING, PASSENGERS NUMBER, PASSENGERS_YEAR NUMBER, LAT FLOAT, LON FLOAT, WARD_CODE STRING, WARD_NAME STRING);



CREATE OR REPLACE TABLE DF_HANDSON.REF.STATION AS
SELECT *, ST_MAKEPOINT(LON, LAT) AS GEO FROM DF_HANDSON.REF.STATION_RAW;

DROP TABLE DF_HANDSON.REF.STATION_RAW;

CREATE OR REPLACE TABLE DF_HANDSON.REF.RAIL (OPERATOR STRING, LINE_NAME STRING, GEOJSON STRING);




CREATE OR REPLACE TABLE DF_HANDSON.REF.MESH_POP_RAW (MESH_CODE STRING, LAT FLOAT, LON FLOAT, POP_2020 FLOAT, POP_65PLUS_2020 FLOAT, WARD_CODE STRING, WARD_NAME STRING);







CREATE OR REPLACE TABLE DF_HANDSON.REF.MESH_POP AS
SELECT *, ST_MAKEPOINT(LON, LAT) AS GEO FROM DF_HANDSON.REF.MESH_POP_RAW;

DROP TABLE DF_HANDSON.REF.MESH_POP_RAW;

CREATE OR REPLACE TABLE DF_HANDSON.REF.SOURCE (DATASET STRING, FILE STRING, PROVIDER STRING, LICENSE STRING);

